	(191, 'accomplishment', 'created', 'App\\Models\\Accomplishment', 'created', 17, 'App\\Models\\User', 28, '{"attributes": {"id": 17, "date": null, "details": "\\nAttended meeting at CAFAMCO with 22 participants; Discussed on matters about Fiesta sa Kaumahan, RSBSA Validation and assisted in the formulation of 2 resolutions to CDA and Landbank.\\n\\nOn-going assistance to 2 FCAs on their registration to DOLE and CDA; a total of 6 documents facilitated.\\n\\nPrepared 1 powerpoint presentation on Cooperative Orientation for 1 FCA at Bayanga\\n", "office_id": 1, "created_at": "2025-06-18T02:43:13.000000Z", "deleted_at": null, "updated_at": "2025-06-18T02:43:13.000000Z", "ref_division_id": 4, "ref_accomplishment_category_id": 10}}', NULL, '2025-06-18 02:43:13', '2025-06-18 02:43:13'),
